#pragma once

// TinyML controller (spec §8, Phase 7, extended to drive the actuators).
//
// A small MLP (5 -> 24 -> 12 -> 12 today; sizes come from model_data.h) with int8 weights (model_data.h, generated by ml/train.py from a
// dataset labelled by an LLM (Gemini) following ml/policy.md). Inputs are the smoothed sensor values
// the rule engine already has; outputs are a state (like edge::State), a window angle and a
// buzzer decision. Plain C++ with no Arduino includes so `pio test -e native` builds it.
//
// Safety: the caller (main.cpp + edge::Engine) keeps the rule engine as the floor. A
// rule-engine DANGER always forces window 90 / buzzer on, and manual overrides win.

#include <stdint.h>

#include "edge_rules.h"

namespace edge_ai {

struct Features {
    float temperature;  // °C (smoothed); NaN = no valid DHT value -> inference is skipped
    float humidity;     // %RH
    float airQuality;   // 0..1000
    float light;        // lux
    bool presence;
};

struct Inference {
    bool valid;         // false when an input was NaN
    edge::State state;  // argmax of the 4 state logits
    int windowAngle;    // one of model::kAngles
    bool buzzer;
    float stateMargin;  // best logit minus second best (confidence proxy)
};

// Raw forward pass. `logits` must hold model::kOutputs floats. Returns false on a NaN input.
bool forward(const Features& f, float* logits);

// forward() + decode. Pure function, ~300 multiply-adds.
Inference classify(const Features& f);

// Debounces the raw decision so the servo does not chase every boundary flicker: a change
// is applied when it has been seen on `kConfirmSamples` consecutive calls (states/buzzer
// escalations apply at once).
class Controller {
public:
    static const uint8_t kConfirmSamples = 2;

    void reset();
    // One call per rule evaluation (1 s). Returns the decision in force after this sample.
    Inference step(const Features& f);
    const Inference& current() const { return current_; }

private:
    Inference current_{false, edge::State::Normal, 0, false, 0};
    Inference pending_{false, edge::State::Normal, 0, false, 0};
    uint8_t pendingCount_ = 0;
};

const char* version();

}  // namespace edge_ai
